import inspect,json,sys
from src.normalize_labels import normalize_labels
DESIGN = json.loads('{"task_id": "STAGE20-LABELS", "contract_version": 1, "cases": [{"id": "empty-input", "intent": "Empty input returns no labels.", "input": "", "expected": []}, {"id": "repeated-separators-and-empty-labels", "intent": "Repeated commas and ordinary-whitespace-only labels are discarded.", "input": " , ,  ,", "expected": []}, {"id": "basic-scan-and-lowercase", "intent": "Comma-separated labels are normalized and ASCII uppercase is lowercased.", "input": " Alpha, BETA,,gamma ", "expected": ["alpha", "beta", "gamma"]}, {"id": "ordinary-whitespace-normalization", "intent": "Boundary ordinary whitespace is trimmed and internal runs collapse to one ASCII space.", "input": "  Alpha \\t beta\\r\\n gamma  ", "expected": ["alpha beta gamma"]}, {"id": "quoted-concatenation", "intent": "Quoted and unquoted text concatenates, quote delimiters are removed, and quoted uppercase is lowercased.", "input": "foo\\" BAR \\"baz", "expected": ["foo bar baz"]}, {"id": "quoted-comma", "intent": "A comma inside quotes is literal while an outside comma separates labels.", "input": "\\"x,y\\",z", "expected": ["x,y", "z"]}, {"id": "escaped-delimiters", "intent": "Escaped commas and quotes are literal characters rather than delimiters.", "input": "a\\\\,b,c\\\\\\"d", "expected": ["a,b", "c\\"d"]}, {"id": "protected-boundary-whitespace", "intent": "Quoted boundary whitespace is preserved while surrounding ordinary whitespace is trimmed.", "input": "  \\" A  \\"  ", "expected": [" a  "]}, {"id": "escaped-whitespace-protection", "intent": "Escaped whitespace is preserved and separates ordinary-whitespace collapsing behavior.", "input": "a\\\\ b  c", "expected": ["a  c"]}, {"id": "quoted-and-escaped-uppercase", "intent": "ASCII uppercase is lowercased even when characters come from quoted or escaped text.", "input": "\\"ABC\\"\\\\D\\\\ E", "expected": ["abcd e"]}, {"id": "deduplication-after-normalization", "intent": "Labels equal after normalization are deduplicated in first-occurrence order.", "input": " Foo,foo,\\"F\\"oo,f\\\\ o", "expected": ["foo", "f o"]}, {"id": "protected-whitespace-only-label", "intent": "An empty quoted label is discarded, while a quoted whitespace-only label is retained.", "input": "a,\\"\\",,   ,\\" \\"", "expected": ["a", " "]}, {"id": "escaped-quote-and-comma-in-quotes", "intent": "Backslash escapes the next character inside quotes, preventing quote or comma syntax.", "input": "\\"a\\\\\\"b,c\\",d", "expected": ["a\\"b,c", "d"]}, {"id": "ordinary-and-protected-mixed-whitespace", "intent": "Protected whitespace preserves multiplicity and breaks ordinary whitespace runs.", "input": "x \\"a \\t b\\" y", "expected": ["x a \\t b y"]}, {"id": "literal-character-preservation", "intent": "Non-delimiter ASCII punctuation and digits are preserved while letters are lowercased.", "input": "ID-42_A!", "expected": ["id-42_a!"]}, {"id": "trailing-backslash-error", "intent": "A trailing unpaired backslash raises a whole-input error even after a valid label.", "input": "ok,done\\\\", "expected": null}, {"id": "unclosed-quote-error", "intent": "An unclosed quote raises a whole-input error even after a valid label.", "input": "ok,\\"bad", "expected": null}, {"id": "escaped-backslash", "intent": "A backslash escapes the following backslash, leaving one literal backslash.", "input": "path\\\\\\\\,end", "expected": ["path\\\\", "end"]}], "properties": ["unique_nonempty_labels", "ascii_lowercase"], "rationale": "These deterministic ASCII-only cases cover empty input, separators and empty labels, ordinary versus protected whitespace, quoting and concatenation, escaping in both modes, literal delimiters, case folding, deduplication, character preservation, and whole-input errors from trailing backslashes or unclosed quotes."}')
results=[]; properties=[]; interface=True
s=inspect.signature(normalize_labels)
interface=(list(s.parameters)==['value'] and s.parameters['value'].annotation in (str,'str') and s.return_annotation in (list[str],'list[str]'))
for c in DESIGN['cases']:
    actual=None; error=None
    try: actual=normalize_labels(c['input'])
    except Exception as exc: error=type(exc).__name__
    passed=(error=='ValueError') if c['expected'] is None else (error is None and type(actual) is list and actual==c['expected'])
    results.append({'id':c['id'],'input':c['input'],'expected':c['expected'],'actual':actual,'error':error,'passed':passed})
    if error is None and type(actual) is list:
        for prop in DESIGN['properties']:
            ok=(all(type(x) is str and x!='' for x in actual) and len(actual)==len(set(actual))) if prop=='unique_nonempty_labels' else all(type(x) is str and not any('A'<=ch<='Z' for ch in x) for x in actual)
            properties.append({'case':c['id'],'property':prop,'passed':ok})
passed=interface and all(c['passed'] for c in results) and all(c['passed'] for c in properties)
print(json.dumps({'passed':passed,'interface':interface,'cases':results,'properties':properties},ensure_ascii=True))
sys.exit(0 if passed else 1)
